input.command:
export DSTASK_GIT_REPO=/tmp/labs/completions-agent/repo
E=/workspace/executable
t(){ printf '=== %s ===\n  ' "$*"; $E _completions "$@" | tr '\n' ' '; echo " [EXIT=$?]"; }
sh(){ printf '=== %s ===\n  CMDS:' "$*"; $E _completions "$@" | grep -c -E '^(next|add|rm|remove|template|log|start|note|notes|stop|done|resolve|context|modify|edit|undo|sync|open|git|show-|bash-|fish-|zsh-|help|version)'; }
for a in "-alpha" "project:apple" "-project:apple" "P1" "P9" "foo" "1" "--" "/" "due:2020-01-01" "template:1" "+" "-" "notaproject:x"; do
  printf '=== last-1="%s" ===\n' "$a"; $E _completions dstask "$a" '' | tr '\n' ' '; echo; done
